#include <iostream>
#include <string>
#include <vector>

class TextDocumentAnalysis {
public:
    static std::string input(const std::string& s) {
        int length = s.length();
        bool inParen = false;
        int totalWords = 0;
        int maxWordSize = 0;
        int currentSize = 0;
        for (int i = 0; i < length; ++i) {
            char c = s[i];
            if (c == '(') {
                if (currentSize > 0) {
                    if (currentSize > maxWordSize) maxWordSize = currentSize;
                    currentSize = 0;
                }
                inParen = true;
            } else if (c == ')') {
                if (currentSize > 0) {
                    totalWords++;
                    currentSize = 0;
                }
                inParen = false;
            } else if (c == '_') {
                if (currentSize > 0) {
                    if (inParen) {
                        totalWords++;
                    } else {
                        if (currentSize > maxWordSize) maxWordSize = currentSize;
                    }
                    currentSize = 0;
                }
            } else {
                currentSize++;
            }
        }
        if (currentSize > 0) {
            if (inParen) {
                totalWords++;
            } else {
                if (currentSize > maxWordSize) maxWordSize = currentSize;
            }
        }
        return std::to_string(maxWordSize) + " " + std::to_string(totalWords);
    }
};

int main() {
    std::string line;
    while (std::getline(std::cin, line)) {
        // Read and discard the first line
        if (!std::getline(std::cin, line))
            break;
        // Process the second line
        std::cout << TextDocumentAnalysis::input(line) << std::endl;
    }
    return 0;
}

